package com.tracker.domain.usecase

import com.tracker.domain.model.TrackerItem
import com.tracker.domain.repository.TrackerRepository
import kotlinx.coroutines.flow.Flow

/**
 * Use case for getting all tracker items
 * Use cases encapsulate business logic and provide a clean API for the presentation layer
 */
class GetAllItemsUseCase(
    private val repository: TrackerRepository
) {
    operator fun invoke(): Flow<List<TrackerItem>> {
        return repository.getAllItems()
    }
}
